const b = $('Chat from Website').first().json.body;
const ctx = $input.first().json;
const role = String(ctx.role || 'guest');
const admin = ['super_admin', 'ops_admin', 'recruiter', 'supervisor', 'finance'];
let mode = 'public';
if (role === 'applicant' || role === 'staff') mode = 'talent';
else if (role.indexOf('hotel_') === 0 || role.indexOf('business_') === 0) mode = 'business';
else if (admin.indexOf(role) >= 0) mode = 'admin';
return [{json: {channel: 'website', mode: mode, user: {id: b.user.id, role: role, name: ctx.name || b.user.name || ''}, conversation_id: b.conversation_id, message: String(b.message).slice(0, 2000), context: ctx}}];

const cq = $('Telegram Trigger').first().json.callback_query;
const parts = String(cq.data || '').split(':');
const decision = parts[0]; const id = parts[1] || '';
if (['approve', 'reject'].indexOf(decision) < 0 || !/^[0-9a-zA-Z_-]{1,64}$/.test(id)) return [{json: {valid: false, query_id: cq.id}}];
return [{json: {valid: true, decision: decision, draft_id: id, query_id: cq.id}}];

const c = String($json.text || '').trim().split(' ')[0].toLowerCase();
const map = {'/today': 'Give me today\'s report.', '/pending': 'List what is waiting for my approval.', '/new': 'What is new since yesterday?'};
return [{json: {text: map[c] || 'Tell me which commands I can use. They are /today, /pending and /new.'}}];

const c = $('Config (telegram)').first().json;
const text = String($json.text || '').slice(0, 2000);
if (!text.trim()) return [];
return [{json: {channel: 'telegram', mode: 'admin', user: {id: c.OWNER_USER_ID, role: 'super_admin', name: 'Owner'}, conversation_id: 'telegram-owner', message: text}}];

const base = $('Prepare Prompt').first().json;
const j = $input.first().json;
const raw = String(j.text !== undefined ? j.text : (j.output !== undefined ? j.output : ''));
const fallback = {ok: false, reply: 'I could not answer just now. Please tap Talk to a human and the team will help you.', actions: [], handoff: true, flags: ['ai_failed'], channel: base.channel, conversation_id: base.conversation_id, user: base.user};
let obj = null;
try { const s = raw.replace(/```json|```/g, '').trim(); const a = s.indexOf('{'), z = s.lastIndexOf('}'); obj = JSON.parse(s.slice(a, z + 1)); } catch (err) {}
if (!obj || typeof obj.reply !== 'string' || !obj.reply.trim()) {
  const plain = raw.trim();
  if (plain && plain.length < 1500 && plain.charAt(0) !== '{') obj = {reply: plain, actions: [], handoff: false, flags: []};
  else return [{json: fallback}];
}
const ALLOWED = ['navigate', 'open_form', 'scroll_to', 'notify', 'handoff_to_human'];
const actions = (Array.isArray(obj.actions) ? obj.actions : []).filter(a => a && ALLOWED.indexOf(a.type) >= 0 && typeof a.target === 'string' && a.target.length < 200 && (a.type !== 'navigate' || a.target.charAt(0) === '/')).slice(0, 3);
const flags = (Array.isArray(obj.flags) ? obj.flags : []).map(String).slice(0, 5);
return [{json: {ok: true, reply: obj.reply.slice(0, 1500), actions: actions, handoff: !!obj.handoff, flags: flags, channel: base.channel, conversation_id: base.conversation_id, user: base.user}}];

const err = $('Error Trigger').first().json;
const wf = (err.workflow && err.workflow.name) || 'unknown';
const sd = $getWorkflowStaticData('global');
sd.last = sd.last || {};
const now = Date.now();
if (sd.last[wf] && now - sd.last[wf] < 3600000) return [];
sd.last[wf] = now;
const cause = String((err.execution && err.execution.error && err.execution.error.message) || 'unknown error').replace(/\s+/g, ' ').slice(0, 150);
const when = new Date().toLocaleString('en-GB', {timeZone: 'Africa/Lagos'});
return [{json: {text: 'StewardBridge alert\nWorkflow: ' + wf + '\nTime: ' + when + '\nCause: ' + cause}}];
